// Copies checks/lib/latin.js into every checks/<element>.js that holds the markers
//   // BEGIN latin.js (generated by checks/lib/inline.mjs, do not edit)
//   // END latin.js
// Run: node checks/lib/inline.mjs (from the bundle directory or anywhere).
import { readFileSync, writeFileSync, readdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const lib = dirname(fileURLToPath(import.meta.url));
const checks = dirname(lib);
const src = readFileSync(join(lib, "latin.js"), "utf8").trimEnd();
const BEGIN = "// BEGIN latin.js (generated by checks/lib/inline.mjs, do not edit)";
const END = "// END latin.js";
let n = 0;
for (const f of readdirSync(checks).filter((x) => x.endsWith(".js"))) {
  const path = join(checks, f), text = readFileSync(path, "utf8");
  const a = text.indexOf(BEGIN), b = text.indexOf(END);
  if (a < 0 || b < a) continue;
  const next = text.slice(0, a) + BEGIN + "\n" + src + "\n" + text.slice(b);
  if (next !== text) { writeFileSync(path, next); n++; }
}
console.log(`inlined latin.js into ${n} file(s)`);
